'use client';
import { FormEvent,useEffect,useState } from 'react';
import Link from 'next/link';
import { api } from '@/lib/api';
type Proposal={id:string;name:string;description:string;initialTopics:string;status:string;supportCount:number;supportedByViewer:boolean;author:{username:string;displayName:string};suggestedParent:{slug:string;name:string}|null;resolutionNote:string|null};
export default function ProposalsPage(){const[items,setItems]=useState<Proposal[]>([]);const[error,setError]=useState('');const[message,setMessage]=useState('');const load=()=>api<Proposal[]>('/governance/proposals').then(setItems).catch(e=>setError(e.message));useEffect(()=>{void load();},[]);async function support(id:string){try{await api(`/governance/proposals/${id}/support`,{method:'POST'});await load();}catch(c){setError(c instanceof Error?c.message:'Ошибка');}}async function create(e:FormEvent<HTMLFormElement>){e.preventDefault();try{const payload=Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>;if(!payload.parentSlug?.trim())delete payload.parentSlug;await api('/governance/proposals',{method:'POST',body:JSON.stringify(payload)});setMessage('Предложение опубликовано');e.currentTarget.reset();await load();}catch(c){setError(c instanceof Error?c.message:'Ошибка');}}return <><div className="section-title"><div><h1>Предложения сообществ</h1><p className="muted">Новые разделы появляются только при реальном спросе и понятном первом наборе тем.</p></div><Link className="button ghost" href="/communities">Каталог</Link></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<div className="two-column"><main className="publication-list">{items.map(p=><article className="card" key={p.id}><div className="publication-topline"><span className="type-label">{p.status}</span>{p.suggestedParent&&<Link href={`/communities/${p.suggestedParent.slug}`}>Внутри {p.suggestedParent.name}</Link>}</div><h2>{p.name}</h2><p>{p.description}</p><div className="notice"><strong>Первые темы</strong><p>{p.initialTopics}</p></div><p className="muted small-text">Предложил @{p.author.username}</p>{p.resolutionNote&&<p className="muted">Решение: {p.resolutionNote}</p>}{p.status==='OPEN'&&<button type="button" className={`button small ${p.supportedByViewer?'secondary':''}`} onClick={()=>support(p.id)}>{p.supportedByViewer?'Убрать поддержку':'Поддержать'} · {p.supportCount}</button>}</article>)}</main><aside className="card"><h2>Предложить сообщество</h2><form onSubmit={create}><label>Название<input name="name" minLength={2} maxLength={80} required/></label><label>Зачем оно нужно<textarea name="description" minLength={30} maxLength={3000} required/></label><label>Примеры первых тем<textarea name="initialTopics" minLength={10} maxLength={2000} required/></label><label>Родительский адрес, необязательно<input name="parentSlug" placeholder="gta-rp"/></label><button className="button">Опубликовать</button></form></aside></div></>}
